UPDATE chat_messages
SET content_html = #{contentHtml}, edited_at = now(), updated_at = now()
WHERE id = #{id}

UPDATE chat_messages
SET reply_count = reply_count + 1, last_reply_at = now(), updated_at = now()
WHERE id = #{id}

UPDATE chat_messages
SET reply_count = GREATEST(reply_count - 1, 0), updated_at = now()
WHERE id = #{id}

UPDATE chat_messages
SET last_reply_at = now(), updated_at = now()
WHERE id = #{id}
